(()=>{const K="mipasantia_maqueta_v1",seed=[{id:1,titulo:"Aprendí a organizar un día de trabajo",empresa:"Nexo Logística",categoria:"Administración",autor:"Sofía Martínez",fecha:"12 jun 2026",contenido:"Mi pasantía me mostró que organizar tareas no es solo hacer listas. Acompañé al equipo de administración, preparé planillas simples y entendí por qué cada dato tiene que estar claro para que el resto pueda trabajar."},{id:2,titulo:"Una primera mirada al diseño profesional",empresa:"Estudio Norte",categoria:"Diseño",autor:"Tomás Rivas",fecha:"03 jun 2026",contenido:"Participé en la preparación de piezas para redes sociales. Lo más valioso fue recibir devoluciones: aprendí a justificar decisiones de color, tipografía y jerarquía antes de abrir cualquier programa."},{id:3,titulo:"Resolver problemas también es programar",empresa:"TecnoSur",categoria:"Tecnología",autor:"Valentina López",fecha:"27 may 2026",contenido:"No programé una aplicación completa, pero ayudé a probar una pantalla y a registrar errores. Descubrí que hacer buenas preguntas y explicar un problema con claridad es una parte importante del trabajo tecnológico."},{id:4,titulo:"Atender bien empieza por escuchar",empresa:"Farmacia Central",categoria:"Salud",autor:"Mateo Silva",fecha:"19 may 2026",contenido:"Acompañé tareas de atención y control de stock. Aprendí que una respuesta clara y respetuosa puede hacer una gran diferencia cuando alguien llega con una consulta."},{id:5,titulo:"Comunicar una idea para que se entienda",empresa:"Comunidad Activa",categoria:"Comunicación",autor:"Lara Benítez",fecha:"08 may 2026",contenido:"Colaboré con una campaña local. Revisamos textos, ordenamos información y pensamos para quién hablábamos. Fue una experiencia muy distinta a escribir solamente para una consigna escolar."}];const cats=["Todas","Administración","Comunicación","Diseño","Tecnología","Salud"];let db=load(),view=location.hash.slice(1)||"inicio",search="",cat="Todas",company="Todas";function load(){let v=localStorage.getItem(K);if(v)return JSON.parse(v);let d={users:[{id:1,nombre:"Alex Romero",email:"estudiante@mipasantia.demo",password:"mipasantia2026",curso:"6° año",bio:"Me interesan la tecnología y las experiencias que ayudan a elegir un camino."}],current:1,posts:seed,favs:[2,3]};localStorage.setItem(K,JSON.stringify(d));return d}function save(){localStorage.setItem(K,JSON.stringify(db))}function esc(s){return String(s).replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[m]))}function user(){return db.users.find(x=>x.id===db.current)}function initials(n){return n.split(" ").map(x=>x[0]).slice(0,2).join("").toUpperCase()}function go(v){location.hash=v;view=v;render();window.scrollTo(0,0)}function postCard(p){let fav=db.favs.includes(p.id);return '<article class="card"><div class="meta"><span class="chip">'+esc(p.categoria)+'</span><span>'+esc(p.empresa)+'</span></div><h3>'+esc(p.titulo)+'</h3><p>'+esc(p.contenido.slice(0,128))+(p.contenido.length>128?"…":"")+'</p><div class="card-actions"><button class="link" data-action="detail" data-id="'+p.id+'">Leer experiencia</button><button class="link" data-action="fav" data-id="'+p.id+'" aria-label="Guardar experiencia">'+(fav?"★ Guardada":"☆ Guardar")+'</button></div></article>'}function nav(){let u=user();return '<header class="top"><div class="bar"><button class="brand" data-go="inicio">Mi<span>Pasantia</span></button><nav class="nav"><button class="'+(view==="inicio"?"on":"")+'" data-go="inicio">Inicio</button><button class="'+(view==="explorar"?"on":"")+'" data-go="explorar">Explorar</button><button class="'+(view==="publicar"?"on":"")+'" data-go="publicar">Publicar</button></nav><div class="session">'+(u?'<span class="session-name">Hola, '+esc(u.nombre.split(" ")[0])+'</span><button class="button ghost small" data-go="perfil">Mi perfil</button><button class="button small" data-action="logout">Salir</button>':'<button class="button ghost small" data-action="login">Ingresar</button><button class="button small" data-action="register">Crear cuenta</button>')+'</div></div></header>'}function home(){return '<main class="page"><section class="hero"><div><span class="eyebrow">Comunidad de experiencias</span><h1>Tu pasantía también puede orientar a alguien más.</h1><p>MiPasantia reúne experiencias reales para conocer ámbitos de trabajo, hacer mejores preguntas y decidir con más información.</p><div class="hero-actions"><button class="button ghost" data-go="explorar">Explorar experiencias</button><button class="button outline" data-go="publicar">Contar la mía</button></div></div><aside class="hero-card"><strong>'+db.posts.length+'</strong><p>experiencias compartidas en esta demostración</p><hr><p>Buscá por empresa, área o tema. Cada recorrido puede empezar con una experiencia concreta.</p></aside></section><section class="metrics"><div class="metric"><strong>6</strong><span>áreas para explorar</span></div><div class="metric"><strong>100%</strong><span>datos ficticios de la maqueta</span></div><div class="metric"><strong>1</strong><span>paso para empezar: leer</span></div></section><section><div class="section-head"><div><h2>Experiencias recientes</h2><p>Ideas concretas para imaginar otros caminos.</p></div><button class="link" data-go="explorar">Ver todas →</button></div><div class="grid">'+db.posts.slice(0,3).map(postCard).join("")+'</div></section></main>'}function explore(){let companies=["Todas",...new Set(db.posts.map(p=>p.empresa))],filtered=db.posts.filter(p=>(cat==="Todas"||p.categoria===cat)&&(company==="Todas"||p.empresa===company)&&[p.titulo,p.empresa,p.autor,p.contenido,p.categoria].join(" ").toLowerCase().includes(search.toLowerCase()));return '<main class="page"><div class="section-head"><div><h1 class="page-title">Explorar experiencias</h1><p>Filtrá para encontrar historias que te resulten útiles.</p></div></div><section class="toolbar"><input id="search" aria-label="Buscar" value="'+esc(search)+'" placeholder="Buscar por tema, empresa o palabra…"><select id="cat">'+cats.map(x=>'<option '+(x===cat?"selected":"")+'>'+x+'</option>').join("")+'</select><select id="company">'+companies.map(x=>'<option '+(x===company?"selected":"")+'>'+esc(x)+'</option>').join("")+'</select><button class="button outline" data-action="clear">Limpiar</button></section><p class="subtle">'+filtered.length+" resultado"+(filtered.length===1?"":"s")+'</p><section class="grid" style="margin-top:16px">'+(filtered.length?filtered.map(postCard).join(""):'<div class="empty" style="grid-column:1/-1"><h3>No encontramos experiencias con esos filtros.</h3><p>Probá con otra palabra o restablecé la búsqueda.</p></div>')+'</section></main>'}function detail(id){let p=db.posts.find(x=>x.id===+id);if(!p){go("explorar");return""}return '<main class="page"><button class="link" data-go="explorar">← Volver a explorar</button><article class="detail" style="margin-top:18px"><div class="meta"><span class="chip">'+esc(p.categoria)+'</span><span>'+esc(p.empresa)+'</span><span>· '+esc(p.fecha)+'</span></div><h1>'+esc(p.titulo)+'</h1><p class="subtle">Compartida por '+esc(p.autor)+'</p><p class="detail-text">'+esc(p.contenido)+'</p><div class="card-actions"><button class="button" data-action="fav" data-id="'+p.id+'">'+(db.favs.includes(p.id)?"★ Guardada":"☆ Guardar experiencia")+'</button><button class="button outline" data-go="publicar">Compartir la mía</button></div></article></main>'}function publish(){let u=user();if(!u)return '<main class="page"><section class="empty"><h1>Compartí cuando tengas una cuenta</h1><p>La maqueta simula una sesión para que el recorrido tenga sentido. Ingresá o creá una cuenta de demostración.</p><button class="button" data-action="login">Ingresar a la maqueta</button></section></main>';return '<main class="page"><div class="section-head"><div><h1 class="page-title">Contá tu experiencia</h1><p>Se guarda solo en este navegador y no se publica en ningún sitio real.</p></div></div><form id="publish-form" class="form-box"><div id="publish-message"></div><div class="form-grid"><div class="field"><label for="title">Título</label><input id="title" name="title" required maxlength="80" placeholder="Ej.: Mi primera semana en…"></div><div class="field"><label for="business">Empresa u organización</label><input id="business" name="business" required maxlength="60" placeholder="Nombre del lugar"></div><div class="field"><label for="category">Área</label><select id="category" name="category" required>'+cats.slice(1).map(x=>'<option>'+x+'</option>').join("")+'</select></div><div class="field"><label for="date">Fecha</label><input id="date" name="date" required type="date"></div></div><div class="field" style="margin-top:16px"><label for="content">¿Qué aprendiste?</label><textarea id="content" name="content" required minlength="40" maxlength="900" placeholder="Contá qué hiciste, qué te sorprendió o qué consejo le darías a otra persona."></textarea></div><div class="form-actions"><button class="button" type="submit">Guardar experiencia</button><span class="subtle">Mínimo 40 caracteres.</span></div></form></main>'}function profile(){let u=user();if(!u)return '<main class="page"><section class="empty"><h1>Tu perfil está esperando</h1><p>Ingresá para ver tus datos y las experiencias que guardaste.</p><button class="button" data-action="login">Ingresar</button></section></main>';let f=db.posts.filter(p=>db.favs.includes(p.id));return '<main class="page"><div class="profile-box"><div class="profile-head"><div class="avatar">'+initials(u.nombre)+'</div><div><h1 class="page-title">'+esc(u.nombre)+'</h1><p class="subtle">'+esc(u.email)+' · '+esc(u.curso||"Estudiante")+'</p></div></div><form id="profile-form"><div id="profile-message"></div><div class="form-grid"><div class="field"><label>Nombre</label><input name="name" required value="'+esc(u.nombre)+'"></div><div class="field"><label>Curso</label><input name="course" required value="'+esc(u.curso||"")+'" placeholder="Ej.: 6° año"></div></div><div class="field" style="margin-top:16px"><label>Sobre mí</label><textarea name="bio" maxlength="300">'+esc(u.bio||"")+'</textarea></div><div class="form-actions"><button class="button" type="submit">Guardar cambios</button><button class="button outline" type="button" data-action="reset">Restablecer datos</button></div></form><section><div class="section-head"><div><h2>Experiencias guardadas</h2></div></div><div class="saved-list">'+(f.length?f.map(p=>'<div class="saved-item"><div><strong>'+esc(p.titulo)+'</strong><div class="subtle">'+esc(p.empresa)+'</div></div><button class="link" data-action="detail" data-id="'+p.id+'">Ver</button></div>').join(""):'<p class="subtle">Todavía no guardaste experiencias. Podés hacerlo desde Explorar.</p>')+'</div></section></div></main>'}function modal(kind){let login=kind==="login";document.querySelector("#modal-root").innerHTML='<div class="modal-back"><section class="modal"><div class="modal-head"><h2>'+ (login?"Ingresar a la maqueta":"Crear cuenta de demostración")+'</h2><button class="icon-btn" data-action="close">×</button></div><form id="auth-form" data-kind="'+kind+'"><div id="auth-message"></div>'+(!login?'<div class="field"><label>Nombre</label><input name="name" required maxlength="50"></div>':"")+'<div class="field"><label>Correo</label><input name="email" required type="email" placeholder="nombre@correo.com"></div><div class="field"><label>Contraseña</label><input name="password" required minlength="6" type="password"></div><button class="button" type="submit">'+(login?"Ingresar":"Crear cuenta")+'</button></form><p class="switch">'+(login?"¿No tenés cuenta? <button data-action=register>Crear una</button>":"¿Ya tenés cuenta? <button data-action=login>Ingresar</button>")+'</p></section></div>'}function close(){document.querySelector("#modal-root").innerHTML=""}function render(){let body=view.startsWith("detalle-")?detail(view.split("-")[1]):view==="explorar"?explore():view==="publicar"?publish():view==="perfil"?profile():home();document.querySelector("#app").innerHTML='<div class="shell">'+nav()+body+'<footer class="footer">MiPasantia · Maqueta funcional con datos ficticios · '+new Date().getFullYear()+'</footer></div>';bind()}function message(id,t,ok){let e=document.querySelector("#"+id);if(e)e.innerHTML='<p class="notice '+(ok?"ok":"error")+'">'+esc(t)+'</p>'}function bind(){document.querySelectorAll("[data-go]").forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll("[data-action=detail]").forEach(b=>b.onclick=()=>go("detalle-"+b.dataset.id));document.querySelectorAll("[data-action=fav]").forEach(b=>b.onclick=()=>{let id=+b.dataset.id,i=db.favs.indexOf(id);i<0?db.favs.push(id):db.favs.splice(i,1);save();render()});document.querySelectorAll("[data-action=login]").forEach(b=>b.onclick=()=>modal("login"));document.querySelectorAll("[data-action=register]").forEach(b=>b.onclick=()=>modal("register"));document.querySelectorAll("[data-action=logout]").forEach(b=>b.onclick=()=>{db.current=null;save();go("inicio")});let c=document.querySelector("[data-action=clear]");if(c)c.onclick=()=>{search="";cat="Todas";company="Todas";render()};let r=document.querySelector("[data-action=reset]");if(r)r.onclick=()=>{if(confirm("Se eliminarán tus cambios de la maqueta. ¿Continuar?")){localStorage.removeItem(K);db=load();go("inicio")}};["search","cat","company"].forEach(id=>{let e=document.querySelector("#"+id);if(e)e.oninput=()=>{search=document.querySelector("#search").value;cat=document.querySelector("#cat").value;company=document.querySelector("#company").value;render()}});let pf=document.querySelector("#publish-form");if(pf)pf.onsubmit=e=>{e.preventDefault();let x=Object.fromEntries(new FormData(pf)),u=user();if(x.content.trim().length<40)return message("publish-message","Contá un poco más: el texto debe tener al menos 40 caracteres.",false);db.posts.unshift({id:Date.now(),titulo:x.title.trim(),empresa:x.business.trim(),categoria:x.category,autor:u.nombre,fecha:new Date(x.date+"T12:00").toLocaleDateString("es-AR",{day:"2-digit",month:"short",year:"numeric"}),contenido:x.content.trim()});save();message("publish-message","La experiencia se guardó en esta maqueta. Ya podés verla en Explorar.",true);pf.reset()};let pr=document.querySelector("#profile-form");if(pr)pr.onsubmit=e=>{e.preventDefault();let x=Object.fromEntries(new FormData(pr));Object.assign(user(),{nombre:x.name.trim(),curso:x.course.trim(),bio:x.bio.trim()});save();message("profile-message","Tus datos se guardaron en este navegador.",true);render()};let af=document.querySelector("#auth-form");if(af)af.onsubmit=e=>{e.preventDefault();let x=Object.fromEntries(new FormData(af)),is=af.dataset.kind==="login";if(is){let u=db.users.find(z=>z.email.toLowerCase()===x.email.toLowerCase()&&z.password===x.password);if(!u)return message("auth-message","Correo o contraseña incorrectos. Probá la cuenta de demostración.",false);db.current=u.id;save();close();go("inicio")}else{if(db.users.some(z=>z.email.toLowerCase()===x.email.toLowerCase()))return message("auth-message","Ese correo ya fue usado en esta maqueta.",false);let u={id:Date.now(),nombre:x.name.trim(),email:x.email.trim(),password:x.password,curso:"Estudiante",bio:""};db.users.push(u);db.current=u.id;save();close();go("perfil")}};let cl=document.querySelector("[data-action=close]");if(cl)cl.onclick=close}window.addEventListener("hashchange",()=>{view=location.hash.slice(1)||"inicio";render()});render()})();
